    nodes = [None if token == "null" else TreeNode(int(token)) for token in tokens]
    child = 1
    for node in nodes:
        if node is not None:
            node.left = nodes[child] if child < len(nodes) else None
            node.right = nodes[child + 1] if child + 1 < len(nodes) else None
            child += 2
    return nodes[0] if nodes else None


# None means no bound on that side.
def valid_between(node: TreeNode | None, low: int | None, high: int | None) -> bool:
    if node is None:
        return True
    if low is not None and node.val <= low:
        return False
    if high is not None and node.val >= high:
        return False
    return valid_between(node.left, low, node.val) and valid_between(node.right, node.val, high)


def is_valid_bst(root: TreeNode | None) -> bool:
    return valid_between(root, None, None)


root = build_tree(input().split())
print("true" if is_valid_bst(root) else "false")

