#include <iostream>
#include <limits>
#include <string>
#include <vector>

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

// Level order: the children of each node come next, null for a missing one.
TreeNode* buildTree(const std::vector<std::string>& tokens) {
    std::vector<TreeNode*> nodes;
    for (const std::string& token : tokens) {
        nodes.push_back(token == "null" ? nullptr : new TreeNode(std::stoi(token)));
    }
    size_t child = 1;
    for (TreeNode* node : nodes) {
        if (node != nullptr) {
            node->left = child < nodes.size() ? nodes[child] : nullptr;
            node->right = child + 1 < nodes.size() ? nodes[child + 1] : nullptr;
            child += 2;
        }
    }
    return nodes.empty() ? nullptr : nodes[0];
}

// The bounds are long long, wider than int, so a value at an int limit
// still fits strictly inside them.
bool validBetween(TreeNode* node, long long low, long long high) {
    if (node == nullptr) {
        return true;
    }
    if (node->val <= low || node->val >= high) {
        return false;
    }
    return validBetween(node->left, low, node->val) && validBetween(node->right, node->val, high);
}

bool isValidBST(TreeNode* root) {
    long long lowest = std::numeric_limits<long long>::min();
    long long highest = std::numeric_limits<long long>::max();
    return validBetween(root, lowest, highest);
}

int main() {
    std::vector<std::string> tokens;
    std::string token;
    while (std::cin >> token) {
        tokens.push_back(token);
    }
    TreeNode* root = buildTree(tokens);
    std::cout << (isValidBST(root) ? "true" : "false") << "\n";
    return 0;
}

